const missingInvoices = $('Audit 1 - Internet Aktif Tanpa Tagihan').all().map(i => i.json).filter(i => i.nomor_internet);
const pendingPayments = $('Audit 2 - Pembayaran Menggantung (>2 Jam)').all().map(i => i.json).filter(i => i.kode_billing_layanan);

let totalPotentialLoss = 0;
missingInvoices.forEach(item => {
  totalPotentialLoss += Number(item.harga_paket || 0);
});

let totalPendingAmount = 0;
pendingPayments.forEach(item => {
  totalPendingAmount += Number(item.nominal || 0);
});

return {
  has_anomalies: (missingInvoices.length > 0 || pendingPayments.length > 0),
  total_unbilled_cust: missingInvoices.length,
  total_unbilled_amount: totalPotentialLoss,
  unbilled_samples: missingInvoices.slice(0, 5),
  total_pending_verif: pendingPayments.length,
  total_pending_amount: totalPendingAmount,
  pending_samples: pendingPayments.slice(0, 5)
};

